import React, { useState } from 'react';
import { FaStar } from 'react-icons/fa';
import toast from 'react-hot-toast';
import { AxiosError } from 'axios';

interface ReviewFormProps {
    productId: string;
    initialData?: {
        rating: number;
        comment: string;
        _id: string;
    };
    onSubmit: (data: { rating: number; comment: string }) => Promise<void>;
    onCancel: () => void;
}

const ReviewForm: React.FC<ReviewFormProps> = ({ productId: _productId, initialData, onSubmit, onCancel }) => {
    const [rating, setRating] = useState(initialData?.rating || 0);
    const [hover, setHover] = useState(0);
    const [comment, setComment] = useState(initialData?.comment || '');
    const [submitting, setSubmitting] = useState(false);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();

        if (rating === 0) {
            return toast.error('Please select a rating');
        }

        if (comment.trim().length < 5) {
            return toast.error('Comment must be at least 5 characters');
        }

        setSubmitting(true);
        try {
            await onSubmit({ rating, comment: comment.trim() });
            toast.success(initialData ? 'Review updated' : 'Review submitted');
        } catch (error: unknown) {
            const err = error as AxiosError<{ message?: string }>;
            toast.error(err.response?.data?.message || 'Failed to submit review');
        } finally {
            setSubmitting(false);
        }
    };

    return (
        <div className="bg-white p-6 rounded-xl border border-gray-100 shadow-sm mb-8">
            <h3 className="text-xl font-bold text-gray-800 mb-4">
                {initialData ? 'Edit Your Review' : 'Write a Review'}
            </h3>

            <form onSubmit={handleSubmit}>
                <div className="mb-4">
                    <label className="block text-sm font-medium text-gray-700 mb-2">Rating</label>
                    <div className="flex gap-1">
                        {[1, 2, 3, 4, 5].map((star) => (
                            <button
                                key={star}
                                type="button"
                                className={`text-2xl transition-colors ${star <= (hover || rating) ? 'text-yellow-400' : 'text-gray-300'
                                    }`}
                                onClick={() => setRating(star)}
                                onMouseEnter={() => setHover(star)}
                                onMouseLeave={() => setHover(0)}
                            >
                                <FaStar />
                            </button>
                        ))}
                    </div>
                </div>

                <div className="mb-6">
                    <label htmlFor="comment" className="block text-sm font-medium text-gray-700 mb-2">
                        Your Feedback
                    </label>
                    <textarea
                        id="comment"
                        rows={4}
                        className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all resize-none"
                        placeholder="What did you like or dislike about this product?"
                        value={comment}
                        onChange={(e) => setComment(e.target.value)}
                        required
                    />
                </div>

                <div className="flex justify-end gap-3">
                    <button
                        type="button"
                        onClick={onCancel}
                        className="px-6 py-2 border border-gray-300 rounded-lg hover:bg-gray-50 transition-colors font-medium text-gray-600"
                    >
                        Cancel
                    </button>
                    <button
                        type="submit"
                        disabled={submitting}
                        className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors font-medium disabled:bg-blue-300"
                    >
                        {submitting ? 'Submitting...' : initialData ? 'Update Review' : 'Post Review'}
                    </button>
                </div>
            </form>
        </div>
    );
};

export default ReviewForm;

import { createContext, useState, useEffect, ReactNode, useContext } from 'react';
import { authService } from '../services/authService';
import { User, RegisterData } from '../types/user';
import toast from 'react-hot-toast';
import { AxiosError } from 'axios';

interface AuthContextType {
    user: User | null;
    isAuthenticated: boolean;
    isLoading: boolean;
    login: (email: string, password: string) => Promise<void>;
    loginHost: (email: string, password: string) => Promise<void>;
    register: (data: RegisterData) => Promise<void>;
    logout: () => void;
    setUser: (user: User | null) => void;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider = ({ children }: { children: ReactNode }) => {
    const [user, setUser] = useState<User | null>(null);
    const [isLoading, setIsLoading] = useState(true);

    // Check if user is logged in on mount
    useEffect(() => {
        const initAuth = async () => {
            const token = localStorage.getItem('accessToken');
            if (token) {
                try {
                    const userData = await authService.getProfile();
                    setUser(userData);
                } catch (error) {
                    console.error('Auth init error:', error);
                    localStorage.clear();
                }
            }
            setIsLoading(false);
        };

        initAuth();
    }, []);

    const login = async (email: string, password: string) => {
        try {
            const response = await authService.login({ email, password });

            if (response.success) {
                localStorage.setItem('accessToken', response.accessToken);
                localStorage.setItem('refreshToken', response.refreshToken);
                setUser(response.user);
                toast.success('Login successful!');
            } else {
                toast.error(response.message || 'Login failed');
                throw new Error(response.message);
            }
        } catch (error: any) {
            const message = error.response?.data?.message || error.message || 'Login failed';
            toast.error(message);
            throw error;
        }
    };

    const register = async (data: RegisterData) => {
        try {
            const response = await authService.register(data);

            if (response.success) {
                toast.success('Registration successful! Please check your email to verify your account.');
            } else {
                toast.error(response.message || 'Registration failed');
                throw new Error(response.message);
            }
        } catch (error: unknown) {
            const err = error as AxiosError<{ message?: string }>;
            const message = err.response?.data?.message || err.message || 'Registration failed';
            toast.error(message);
            throw error;
        }
    };

    const loginHost = async (email: string, password: string) => {
        try {
            const response = await authService.loginHost({ email, password });
            if (response.success) {
                localStorage.setItem('accessToken', response.accessToken);
                localStorage.setItem('refreshToken', response.refreshToken);
                setUser(response.seller);
                toast.success('Welcome back, Seller!');
            } else {
                toast.error(response.message || 'Login failed');
                throw new Error(response.message);
            }
        } catch (error: any) {
            const message = error.response?.data?.message || error.message || 'Login failed';
            toast.error(message);
            throw error;
        }
    };

    const logout = () => {
        authService.logout();
        setUser(null);
        toast.success('Logged out successfully');
    };

    return (
        <AuthContext.Provider value={{
            user,
            isAuthenticated: !!user,
            isLoading,
            login,
            loginHost,
            register,
            logout,
            setUser
        }}>
            {children}
        </AuthContext.Provider>
    );
};

// Custom hook to use auth context
export const useAuth = () => {
    const context = useContext(AuthContext);
    if (context === undefined) {
        throw new Error('useAuth must be used within an AuthProvider');
    }
    return context;
};

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import toast from 'react-hot-toast';

export interface CartItem {
    _id: string;
    name: string;
    price: number;
    imageUrl: string;
    quantity: number;
    maxQuantity: number;
}

interface CartContextType {
    cartItems: CartItem[];
    addToCart: (product: any, quantity: number) => void;
    removeFromCart: (productId: string) => void;
    updateQuantity: (productId: string, quantity: number) => void;
    clearCart: () => void;
    cartTotal: number;
    cartCount: number;
}

const CartContext = createContext<CartContextType | undefined>(undefined);

export const useCart = () => {
    const context = useContext(CartContext);
    if (!context) {
        throw new Error('useCart must be used within a CartProvider');
    }
    return context;
};

export const CartProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
    const [cartItems, setCartItems] = useState<CartItem[]>([]);

    // Load from local storage on mount
    useEffect(() => {
        const savedCart = localStorage.getItem('cart');
        if (savedCart) {
            try {
                setCartItems(JSON.parse(savedCart));
            } catch (error) {
                console.error("Failed to parse cart from local storage", error);
                localStorage.removeItem('cart');
            }
        }
    }, []);

    // Save to local storage on change
    useEffect(() => {
        localStorage.setItem('cart', JSON.stringify(cartItems));
    }, [cartItems]);

    const addToCart = (product: any, quantity: number) => {
        const existingItem = cartItems.find(item => item._id === product._id);

        if (existingItem) {
            const newQuantity = Math.min(existingItem.quantity + quantity, product.quantity);
            if (newQuantity === existingItem.quantity) {
                toast.error(`Cannot add more. Max stock is ${product.quantity}`);
                return;
            }
            setCartItems(prevItems =>
                prevItems.map(item =>
                    item._id === product._id ? { ...item, quantity: newQuantity } : item
                )
            );
            toast.success('Cart updated');
        } else {
            setCartItems(prevItems => [...prevItems, {
                _id: product._id,
                name: product.name,
                price: product.price,
                imageUrl: product.imageUrl?.url || product.imageUrl,
                quantity: quantity,
                maxQuantity: product.quantity
            }]);
            toast.success('Added to cart');
        }
    };

    const removeFromCart = (productId: string) => {
        setCartItems(prevItems => prevItems.filter(item => item._id !== productId));
        toast.success('Removed from cart');
    };

    const updateQuantity = (productId: string, quantity: number) => {
        setCartItems(prevItems =>
            prevItems.map(item => {
                if (item._id === productId) {
                    const newQty = Math.max(1, Math.min(quantity, item.maxQuantity));
                    return { ...item, quantity: newQty };
                }
                return item;
            })
        );
    };

    const clearCart = () => {
        setCartItems([]);
    };

    const cartTotal = cartItems.reduce((total, item) => total + (item.price * item.quantity), 0);
    const cartCount = cartItems.reduce((count, item) => count + item.quantity, 0);

    return (
        <CartContext.Provider value={{ cartItems, addToCart, removeFromCart, updateQuantity, clearCart, cartTotal, cartCount }}>
            {children}
        </CartContext.Provider>
    );
};

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useCart } from '../contexts/CartContext';
import { addressService, Address } from '../services/addressService';
import { paymentService } from '../services/paymentService';
import { FaMapMarkerAlt, FaCreditCard, FaShoppingBag, FaShieldAlt } from 'react-icons/fa';
import toast from 'react-hot-toast';

declare global {
    interface Window {
        Razorpay: any;
    }
}

const Checkout: React.FC = () => {
    const { cartItems, cartTotal, clearCart } = useCart();
    const navigate = useNavigate();
    const [addresses, setAddresses] = useState<Address[]>([]);
    const [selectedAddressId, setSelectedAddressId] = useState<string>('');
    const [loading, setLoading] = useState(true);
    const [isProcessing, setIsProcessing] = useState(false);

    const taxAmount = Number((cartTotal * 0.18).toFixed(0));
    const finalAmount = cartTotal + taxAmount;

    useEffect(() => {
        if (cartItems.length === 0) {
            navigate('/cart');
            return;
        }
        fetchAddresses();
    }, [cartItems, navigate]);

    const fetchAddresses = async () => {
        try {
            const response = await addressService.getAddresses();
            const fetchedAddresses = response.allAddress || response.address || response.addresses || (Array.isArray(response) ? response : []);
            setAddresses(fetchedAddresses);
            if (fetchedAddresses.length > 0) {
                setSelectedAddressId(fetchedAddresses[0]._id!);
            }
        } catch (error) {
            console.error("Failed to fetch addresses", error);
            toast.error("Could not load your addresses");
        } finally {
            setLoading(false);
        }
    };

    const handlePayment = async () => {
        if (!selectedAddressId) {
            toast.error("Please select a delivery address");
            return;
        }

        setIsProcessing(true);
        try {
            // Step 1: Create Order in Backend
            console.log("Cart Items at Checkout:", cartItems);
            const checkoutData = {
                products: cartItems.map(item => ({
                    product: item._id || (item as any).id,
                    quantity: item.quantity
                })),
                addressId: selectedAddressId,
                totalAmount: finalAmount
            };
            console.log("Checkout Payload:", checkoutData);

            const response = await paymentService.checkout(checkoutData);

            if (response.success) {
                const { razorpayOrder, order } = response;

                // Step 2: Initialize Razorpay
                const options = {
                    key: razorpayOrder.key,
                    amount: razorpayOrder.amount,
                    currency: razorpayOrder.currency,
                    name: 'PharmaNest',
                    description: 'Purchase of health essentials',
                    order_id: razorpayOrder.id,
                    handler: async (response: any) => {
                        try {
                            // Step 3: Verify Payment
                            const verificationData = {
                                razorpay_order_id: response.razorpay_order_id,
                                razorpay_payment_id: response.razorpay_payment_id,
                                razorpay_signature: response.razorpay_signature,
                                orderId: order._id
                            };

                            const verifyRes = await paymentService.verifyPayment(verificationData);
                            if (verifyRes.success) {
                                toast.success("Order placed successfully!");
                                clearCart();
                                navigate('/user/orders');
                            } else {
                                toast.error("Payment verification failed");
                            }
                        } catch (error) {
                            console.error("Verification error", error);
                            toast.error("An error occurred during verification");
                        }
                    },
                    prefill: {
                        name: '', // Will be filled by backend/user session anyway
                        email: '',
                        contact: ''
                    },
                    theme: {
                        color: "#2563eb" // blue-600
                    }
                };

                const rzp = new window.Razorpay(options);
                rzp.open();
            } else {
                toast.error(response.message || "Checkout failed");
            }
        } catch (error: any) {
            console.error("Checkout error", error);
            toast.error(error.response?.data?.message || "Something went wrong. Please try again.");
        } finally {
            setIsProcessing(false);
        }
    };

    if (loading) {
        return (
            <div className="min-h-screen flex items-center justify-center">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-gray-50 py-12 px-4 sm:px-6 lg:px-8">
            <div className="max-w-5xl mx-auto">
                <h1 className="text-3xl font-extrabold text-gray-900 mb-8 flex items-center">
                    <FaShieldAlt className="mr-3 text-blue-600" /> Secure Checkout
                </h1>

                <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                    {/* Left Column: Addressing */}
                    <div className="space-y-6">
                        <section className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
                            <h2 className="text-xl font-bold text-gray-800 mb-6 flex items-center">
                                <FaMapMarkerAlt className="mr-2 text-red-500" /> Delivery Address
                            </h2>

                            {addresses.length > 0 ? (
                                <div className="space-y-4">
                                    {addresses.map((addr) => (
                                        <label
                                            key={addr._id}
                                            className={`block relative p-4 rounded-xl border-2 cursor-pointer transition-all ${selectedAddressId === addr._id
                                                ? 'border-blue-600 bg-blue-50'
                                                : 'border-gray-100 hover:border-blue-200'
                                                }`}
                                        >
                                            <input
                                                type="radio"
                                                name="address"
                                                className="hidden"
                                                checked={selectedAddressId === addr._id}
                                                onChange={() => setSelectedAddressId(addr._id!)}
                                            />
                                            <span className="font-bold text-gray-800">{addr.name}</span>
                                            <p className="text-sm text-gray-600 mt-1">{addr.address}</p>
                                            <p className="text-sm text-gray-600">Ph: {addr.mobileNum} | Pin: {addr.pincode}</p>
                                        </label>
                                    ))}
                                    <button
                                        onClick={() => navigate('/user/profile')}
                                        className="text-blue-600 text-sm font-semibold hover:underline"
                                    >
                                        + Add new address
                                    </button>
                                </div>
                            ) : (
                                <div className="text-center py-6">
                                    <p className="text-gray-500 mb-4">No addresses found</p>
                                    <button
                                        onClick={() => navigate('/user/profile')}
                                        className="px-6 py-2 bg-blue-600 text-white rounded-lg font-bold"
                                    >
                                        Add Address
                                    </button>
                                </div>
                            )}
                        </section>

                        <section className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
                            <h2 className="text-xl font-bold text-gray-800 mb-6 flex items-center">
                                <FaCreditCard className="mr-2 text-blue-600" /> Payment Method
                            </h2>
                            <div className="p-4 rounded-xl bg-gray-50 border border-gray-100 flex items-center">
                                <span className="p-2 bg-white rounded-lg shadow-sm mr-4">
                                    <img src="https://razorpay.com/favicon.png" alt="Razorpay" className="w-6 h-6" />
                                </span>
                                <div>
                                    <p className="font-bold text-gray-800">Razorpay Secure</p>
                                    <p className="text-xs text-gray-500 text-nowrap">UPI, Cards, NetBanking, Wallets</p>
                                </div>
                                <div className="ml-auto text-blue-600">
                                    <FaShieldAlt />
                                </div>
                            </div>
                        </section>
                    </div>

                    {/* Right Column: Order Summary */}
                    <div className="space-y-6">
                        <section className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 sticky top-24">
                            <h2 className="text-xl font-bold text-gray-800 mb-6 flex items-center">
                                <FaShoppingBag className="mr-2 text-emerald-500" /> Order Summary
                            </h2>

                            <div className="max-h-60 overflow-y-auto mb-6 pr-2 custom-scrollbar">
                                {cartItems.map((item) => (
                                    <div key={item._id} className="flex gap-4 mb-4 pb-4 border-b border-gray-50">
                                        <div className="w-16 h-16 bg-gray-50 rounded-lg flex items-center justify-center p-1">
                                            <img src={item.imageUrl} alt="" className="max-h-full object-contain" />
                                        </div>
                                        <div className="flex-1">
                                            <h4 className="text-sm font-bold text-gray-800 line-clamp-1">{item.name}</h4>
                                            <p className="text-xs text-gray-500">Qty: {item.quantity} ├ù Γé╣{item.price}</p>
                                        </div>
                                        <div className="text-sm font-bold text-gray-800">
                                            Γé╣{item.price * item.quantity}
                                        </div>
                                    </div>
                                ))}
                            </div>

                            <div className="space-y-3 mb-6">
                                <div className="flex justify-between text-gray-600 text-sm">
                                    <span>Subtotal</span>
                                    <span>Γé╣{cartTotal}</span>
                                </div>
                                <div className="flex justify-between text-gray-600 text-sm">
                                    <span>Shipping</span>
                                    <span className="text-green-600 font-bold text-nowrap">FREE</span>
                                </div>
                                <div className="flex justify-between text-gray-600 text-sm">
                                    <span>GST (18%)</span>
                                    <span>Γé╣{taxAmount}</span>
                                </div>
                                <div className="border-t border-gray-100 pt-3 flex justify-between items-center">
                                    <span className="text-lg font-bold text-gray-800">Amount Payable</span>
                                    <span className="text-2xl font-black text-blue-600">Γé╣{finalAmount}</span>
                                </div>
                            </div>

                            <button
                                onClick={handlePayment}
                                disabled={isProcessing || addresses.length === 0}
                                className={`w-full py-4 rounded-xl font-bold flex items-center justify-center transition-all shadow-lg ${isProcessing || addresses.length === 0
                                    ? 'bg-gray-300 cursor-not-allowed'
                                    : 'bg-blue-600 text-white hover:bg-blue-700 hover:scale-[1.02] shadow-blue-100'
                                    }`}
                            >
                                {isProcessing ? (
                                    <>
                                        <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-white mr-3"></div>
                                        Processing...
                                    </>
                                ) : (
                                    `Pay Γé╣${finalAmount}`
                                )}
                            </button>

                            <p className="text-center text-[10px] text-gray-400 mt-4">
                                By clicking Pay, you agree to PharmaNest's Terms and Conditions.
                            </p>
                        </section>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default Checkout;

import { useState, useRef } from 'react';
import { productService } from '../../services/productService';
import { Upload, FileText, CheckCircle2, AlertCircle, RefreshCcw, DollarSign, ArrowLeft, Download, Loader2 } from 'lucide-react';
import toast from 'react-hot-toast';
import { useNavigate } from 'react-router-dom';

const BulkOperations = () => {
    const [file, setFile] = useState<File | null>(null);
    const [uploading, setUploading] = useState(false);
    const [uploadSuccess, setUploadSuccess] = useState<number | null>(null);
    const fileInputRef = useRef<HTMLInputElement>(null);
    const navigate = useNavigate();

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const selectedFile = e.target.files[0];
            if (selectedFile.name.endsWith('.csv')) {
                setFile(selectedFile);
                setUploadSuccess(null);
            } else {
                toast.error('Please upload a CSV file');
            }
        }
    };

    const handleUpload = async () => {
        if (!file) return;

        setUploading(true);
        try {
            const response = await productService.uploadBulkProducts(file);
            if (response.success) {
                toast.success(`Successfully uploaded ${response.count} products!`);
                setUploadSuccess(response.count);
                setFile(null);
            }
        } catch (error: any) {
            console.error('Upload error:', error);
            const message = error.response?.data?.message || 'Upload failed. Check your CSV format.';
            toast.error(message);
        } finally {
            setUploading(false);
        }
    };

    const downloadTemplate = () => {
        const headers = 'name,brand,form,strength,category,price,mainPrice,quantity,sku,description,imageUrl\n';
        const sampleRows = 'Paracetamol 500mg,Dolo,Tablet,500mg,Medicine,30,40,100,SKU-DOLO-500,Pain reliever and fever reducer,\n';
        const blob = new Blob([headers + sampleRows], { type: 'text/csv' });
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'PharmaNest_Bulk_Template.csv';
        a.click();
    };

    return (
        <div className="min-h-screen bg-gray-50 py-12">
            <div className="max-w-4xl mx-auto px-4">

                <button
                    onClick={() => navigate('/host/inventory')}
                    className="flex items-center gap-2 text-gray-500 hover:text-blue-600 font-semibold mb-8 transition"
                >
                    <ArrowLeft size={18} />
                    Back to Inventory
                </button>

                <div className="mb-10 text-center">
                    <h1 className="text-4xl font-black text-gray-900 mb-2">Bulk Operations</h1>
                    <p className="text-gray-500">Fast-track your business by managing hundreds of products at once</p>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">

                    {/* CSV Upload Section */}
                    <div className="bg-white p-8 rounded-[2rem] shadow-sm border border-gray-100 relative overflow-hidden group">
                        <div className="absolute top-0 right-0 p-6 opacity-5 group-hover:scale-110 transition-transform">
                            <FileText size={120} />
                        </div>

                        <div className="h-14 w-14 bg-blue-50 rounded-2xl flex items-center justify-center text-blue-600 mb-6">
                            <Upload size={28} />
                        </div>

                        <h2 className="text-2xl font-bold text-gray-900 mb-2">Bulk Product Import</h2>
                        <p className="text-sm text-gray-500 mb-8">Upload a CSV file to add new products to your catalogue in seconds.</p>

                        <div
                            onClick={() => fileInputRef.current?.click()}
                            className={`border-2 border-dashed rounded-2xl p-8 text-center cursor-pointer transition-all ${file ? 'border-blue-500 bg-blue-50' : 'border-gray-200 hover:border-blue-400 hover:bg-gray-50'
                                }`}
                        >
                            <input
                                type="file"
                                ref={fileInputRef}
                                onChange={handleFileChange}
                                className="hidden"
                                accept=".csv"
                            />
                            {file ? (
                                <div className="flex flex-col items-center">
                                    <CheckCircle2 className="text-blue-600 mb-2" size={32} />
                                    <p className="font-bold text-gray-900 truncate max-w-full">{file.name}</p>
                                    <p className="text-xs text-blue-500 font-bold uppercase mt-1">Ready to upload</p>
                                </div>
                            ) : (
                                <div className="flex flex-col items-center text-gray-400">
                                    <Upload className="mb-2" size={32} />
                                    <p className="font-medium">Drop your CSV here</p>
                                    <p className="text-xs text-gray-400">or click to browse</p>
                                </div>
                            )}
                        </div>

                        {uploadSuccess && (
                            <div className="mt-4 p-4 bg-green-50 rounded-xl flex items-center gap-3 text-green-700">
                                <CheckCircle2 size={20} />
                                <p className="text-sm font-bold">Successfully imported {uploadSuccess} products!</p>
                            </div>
                        )}

                        <div className="mt-8 flex gap-3">
                            <button
                                onClick={handleUpload}
                                disabled={!file || uploading}
                                className="flex-1 bg-blue-600 text-white py-3 rounded-xl font-bold hover:bg-blue-700 disabled:bg-gray-200 disabled:text-gray-400 transition-all flex items-center justify-center gap-2"
                            >
                                {uploading ? (
                                    <>
                                        <Loader2 className="animate-spin" size={20} />
                                        Processing...
                                    </>
                                ) : 'Start Import'}
                            </button>
                            <button
                                onClick={downloadTemplate}
                                className="px-4 py-3 bg-gray-100 text-gray-700 rounded-xl hover:bg-gray-200 transition"
                                title="Download Template"
                            >
                                <Download size={20} />
                            </button>
                        </div>
                    </div>

                    {/* Batch Price Edit - Placeholder / Future Link */}
                    <div className="bg-white p-8 rounded-[2rem] shadow-sm border border-gray-100 relative overflow-hidden group opacity-80 bg-gray-50/50">
                        <div className="absolute top-0 right-0 p-6 opacity-5">
                            <DollarSign size={120} />
                        </div>

                        <div className="h-14 w-14 bg-amber-50 rounded-2xl flex items-center justify-center text-amber-600 mb-6">
                            <RefreshCcw size={28} />
                        </div>

                        <h2 className="text-2xl font-bold text-gray-900 mb-2 text-gray-400">Batch Price Editor</h2>
                        <p className="text-sm text-gray-500 mb-8">Quickly update prices for multiple products without opening individual pages.</p>

                        <div className="bg-white/50 border border-gray-100 rounded-2xl p-8 flex flex-col items-center justify-center text-center">
                            <AlertCircle className="text-amber-500 mb-2" size={32} />
                            <p className="font-bold text-gray-600">Coming Soon</p>
                            <p className="text-xs text-gray-400">We're building a spreadsheet-like editor for you!</p>
                        </div>

                        <button
                            disabled
                            className="mt-8 w-full bg-gray-100 text-gray-400 py-3 rounded-xl font-bold cursor-not-allowed"
                        >
                            Open Batch Editor
                        </button>
                    </div>

                </div>

                {/* Instructions */}
                <div className="mt-12 bg-blue-600 rounded-[2rem] p-10 text-white relative overflow-hidden shadow-xl shadow-blue-100">
                    <div className="relative z-10">
                        <h3 className="text-2xl font-bold mb-6">Tips for a Perfect Import</h3>
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                            <div>
                                <h4 className="font-bold text-blue-100 mb-2">1. Required Fields</h4>
                                <p className="text-sm opacity-90">Ensure `name`, `brand`, and `price` are always present. Use full category names like `Medicine`.</p>
                            </div>
                            <div>
                                <h4 className="font-bold text-blue-100 mb-2">2. SKU Format</h4>
                                <p className="text-sm opacity-90">SKUs must be unique. If left blank, we'll generate professional internal SKUs for you.</p>
                            </div>
                            <div>
                                <h4 className="font-bold text-blue-100 mb-2">3. Price Check</h4>
                                <p className="text-sm opacity-90">Set `mainPrice` higher than `price` to show beautiful discount percentage badges automatically.</p>
                            </div>
                        </div>
                    </div>
                    {/* Decorative Background */}
                    <div className="absolute -bottom-10 -right-10 h-64 w-64 bg-blue-500/30 rounded-full blur-3xl"></div>
                </div>

            </div>
        </div>
    );
};

export default BulkOperations;

import { useState, useEffect } from 'react';
import { productService } from '../../services/productService';
import {
    TrendingUp,
    Package,
    ShoppingCart,
    AlertTriangle,
    Star,
    ArrowUpRight,
    DollarSign
} from 'lucide-react';
import {
    AreaChart,
    Area,
    XAxis,
    YAxis,
    CartesianGrid,
    Tooltip,
    ResponsiveContainer
} from 'recharts';
import { DashboardStats, SalesTrend, TopProduct } from '../../services/productService';

const SellerDashboard = () => {
    const [stats, setStats] = useState<DashboardStats | null>(null);
    const [trends, setTrends] = useState<SalesTrend[]>([]);
    const [topProducts, setTopProducts] = useState<TopProduct[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        loadDashboardData();
    }, []);

    const loadDashboardData = async () => {
        setLoading(true);
        try {
            const [statsRes, trendsRes, topRes] = await Promise.all([
                productService.getDashboardStats(),
                productService.getSalesTrends(),
                productService.getTopProducts()
            ]);

            if (statsRes.success) setStats(statsRes.stats);
            if (trendsRes.success) setTrends(trendsRes.trends);
            if (topRes.success) setTopProducts(topRes.products);
        } catch (error) {
            console.error('Failed to load dashboard data', error);
        } finally {
            setLoading(false);
        }
    };

    if (loading) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-gray-50">
                <div className="text-center">
                    <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto"></div>
                    <p className="mt-4 text-gray-500 font-medium">Loading analytics...</p>
                </div>
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-gray-50 py-8">
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">

                {/* Header */}
                <div className="mb-8">
                    <h1 className="text-3xl font-black text-gray-900">Seller Dashboard</h1>
                    <p className="text-gray-500 mt-1">Overview of your business performance</p>
                </div>

                {/* Stats Grid */}
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
                    {/* Revenue Card */}
                    <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 transition hover:shadow-md">
                        <div className="flex justify-between items-start mb-4">
                            <div className="p-3 bg-green-50 rounded-xl">
                                <DollarSign className="text-green-600" size={24} />
                            </div>
                            <span className="text-xs font-bold text-green-600 bg-green-100 px-2 py-1 rounded-full flex items-center gap-1">
                                <TrendingUp size={12} /> +12%
                            </span>
                        </div>
                        <p className="text-gray-500 text-sm font-medium">Total Revenue</p>
                        <h3 className="text-3xl font-bold text-gray-900 mt-1">Γé╣{stats?.revenue?.toLocaleString()}</h3>
                    </div>

                    {/* Orders Card */}
                    <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 transition hover:shadow-md">
                        <div className="flex justify-between items-start mb-4">
                            <div className="p-3 bg-blue-50 rounded-xl">
                                <ShoppingCart className="text-blue-600" size={24} />
                            </div>
                        </div>
                        <p className="text-gray-500 text-sm font-medium">Total Orders</p>
                        <h3 className="text-3xl font-bold text-gray-900 mt-1">{stats?.orders}</h3>
                    </div>

                    {/* Products Card */}
                    <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 transition hover:shadow-md">
                        <div className="flex justify-between items-start mb-4">
                            <div className="p-3 bg-purple-50 rounded-xl">
                                <Package className="text-purple-600" size={24} />
                            </div>
                            <div className="flex gap-2">
                                <span className="text-xs font-bold text-gray-500 bg-gray-100 px-2 py-1 rounded-full">
                                    {stats?.activeProducts} Active
                                </span>
                            </div>
                        </div>
                        <p className="text-gray-500 text-sm font-medium">Total Products</p>
                        <h3 className="text-3xl font-bold text-gray-900 mt-1">{(stats?.activeProducts || 0) + (stats?.lowStockAlerts || 0)}</h3>
                    </div>

                    {/* Low Stock Card */}
                    <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 transition hover:shadow-md">
                        <div className="flex justify-between items-start mb-4">
                            <div className="p-3 bg-red-50 rounded-xl">
                                <AlertTriangle className="text-red-600" size={24} />
                            </div>
                        </div>
                        <p className="text-gray-500 text-sm font-medium">Low Stock Alerts</p>
                        <h3 className="text-3xl font-bold text-gray-900 mt-1">{stats?.lowStockAlerts}</h3>
                    </div>
                </div>

                {/* Charts Section */}
                <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 mb-8">
                    {/* Sales Trend Chart */}
                    <div className="bg-white p-6 rounded-3xl shadow-sm border border-gray-100 lg:col-span-2">
                        <div className="flex justify-between items-center mb-6">
                            <h3 className="text-xl font-bold text-gray-900">Sales Trend</h3>
                            <select className="bg-gray-50 border border-gray-200 text-gray-700 text-sm rounded-lg px-3 py-2 cursor-pointer outline-none">
                                <option>Last 30 Days</option>
                            </select>
                        </div>
                        <div className="h-[300px] w-full">
                            <ResponsiveContainer width="100%" height="100%">
                                <AreaChart data={trends} margin={{ top: 10, right: 10, left: 0, bottom: 0 }}>
                                    <defs>
                                        <linearGradient id="colorRevenue" x1="0" y1="0" x2="0" y2="1">
                                            <stop offset="5%" stopColor="#2563eb" stopOpacity={0.2} />
                                            <stop offset="95%" stopColor="#2563eb" stopOpacity={0} />
                                        </linearGradient>
                                    </defs>
                                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#E5E7EB" />
                                    <XAxis
                                        dataKey="date"
                                        axisLine={false}
                                        tickLine={false}
                                        tick={{ fill: '#9CA3AF', fontSize: 12 }}
                                        tickFormatter={(str) => {
                                            const d = new Date(str);
                                            return `${d.getDate()}/${d.getMonth() + 1}`;
                                        }}
                                    />
                                    <YAxis
                                        axisLine={false}
                                        tickLine={false}
                                        tick={{ fill: '#9CA3AF', fontSize: 12 }}
                                        tickFormatter={(val) => `Γé╣${val}`}
                                    />
                                    <Tooltip
                                        contentStyle={{ backgroundColor: '#fff', borderRadius: '12px', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)', border: 'none' }}
                                        formatter={(value: any) => [`Γé╣${value}`, 'Revenue']}
                                    />
                                    <Area type="monotone" dataKey="revenue" stroke="#2563eb" strokeWidth={3} fillOpacity={1} fill="url(#colorRevenue)" />
                                </AreaChart>
                            </ResponsiveContainer>
                        </div>
                    </div>

                    {/* Rating Overview */}
                    <div className="bg-white p-6 rounded-3xl shadow-sm border border-gray-100">
                        <h3 className="text-xl font-bold text-gray-900 mb-6">Customer Happiness</h3>
                        <div className="flex flex-col items-center justify-center py-8">
                            <div className="relative mb-4">
                                <div className="h-40 w-40 rounded-full border-[12px] border-gray-100 flex items-center justify-center">
                                    <div className="text-center">
                                        <span className="text-4xl font-black text-gray-900 block">{stats?.averageRating}</span>
                                        <span className="text-sm text-gray-400 font-bold uppercase">out of 5</span>
                                    </div>
                                </div>
                                <div
                                    className="absolute top-0 left-0 h-40 w-40 rounded-full border-[12px] border-yellow-400 border-t-transparent border-l-transparent -rotate-45"
                                    style={{ clipPath: 'polygon(50% 0%, 100% 0, 100% 100%, 50% 100%)' }} // Fake progress ring
                                ></div>
                            </div>
                            <div className="flex items-center gap-2 text-gray-500 font-medium">
                                <Star className="fill-yellow-400 text-yellow-400" size={20} />
                                <span>Based on {stats?.totalReviews} reviews</span>
                            </div>
                        </div>
                    </div>
                </div>

                {/* Top Products Table */}
                <div className="bg-white rounded-3xl shadow-sm border border-gray-100 overflow-hidden">
                    <div className="p-6 border-b border-gray-100 flex justify-between items-center">
                        <h3 className="text-xl font-bold text-gray-900">Top Selling Products</h3>
                        <button className="text-blue-600 font-bold text-sm hover:underline flex items-center gap-1">
                            View All <ArrowUpRight size={16} />
                        </button>
                    </div>
                    <div className="overflow-x-auto">
                        <table className="w-full text-left">
                            <thead className="bg-gray-50">
                                <tr>
                                    <th className="px-6 py-4 text-xs font-bold text-gray-400 uppercase">Product</th>
                                    <th className="px-6 py-4 text-xs font-bold text-gray-400 uppercase">Price</th>
                                    <th className="px-6 py-4 text-xs font-bold text-gray-400 uppercase">Sold</th>
                                    <th className="px-6 py-4 text-xs font-bold text-gray-400 uppercase">Revenue</th>
                                    <th className="px-6 py-4 text-xs font-bold text-gray-400 uppercase">Status</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-50">
                                {topProducts.map((product) => (
                                    <tr key={product._id} className="hover:bg-gray-50/50 transition">
                                        <td className="px-6 py-4">
                                            <div className="flex items-center gap-3">
                                                <div className="h-10 w-10 rounded-lg bg-gray-50 flex items-center justify-center border border-gray-100">
                                                    <img src={product.imageUrl?.url} alt="" className="h-8 w-8 object-contain" />
                                                </div>
                                                <span className="font-bold text-gray-700">{product.name}</span>
                                            </div>
                                        </td>
                                        <td className="px-6 py-4 font-medium text-gray-600">Γé╣{product.price}</td>
                                        <td className="px-6 py-4 font-bold text-gray-900">{product.soldQuantity} units</td>
                                        <td className="px-6 py-4 font-bold text-green-600">Γé╣{(product.price * product.soldQuantity).toLocaleString()}</td>
                                        <td className="px-6 py-4">
                                            <span className={`px-2 py-1 rounded-full text-xs font-bold ${product.stockStatus === 'in_stock' ? 'bg-green-100 text-green-700' :
                                                product.stockStatus === 'low_stock' ? 'bg-amber-100 text-amber-700' :
                                                    'bg-red-100 text-red-700'
                                                }`}>
                                                {product.stockStatus.replace('_', ' ')}
                                            </span>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>

            </div>
        </div>
    );
};

export default SellerDashboard;

import React, { useEffect, useState } from 'react';
import { useParams, Link } from 'react-router-dom';
import UserSidebar from '../../components/layout/UserSidebar';
import { orderService, Order } from '../../services/orderService';
import { FaArrowLeft, FaBox, FaTruck, FaCheckCircle, FaDownload } from 'react-icons/fa';

const OrderDetails: React.FC = () => {
    const { id } = useParams<{ id: string }>();
    const [order, setOrder] = useState<any>(null); // Using any for flexibility with populated fields
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        if (id) {
            fetchOrderDetails(id);
        }
    }, [id]);

    const fetchOrderDetails = async (orderId: string) => {
        try {
            const data = await orderService.getOrderDetails(orderId);
            setOrder(data.order);
        } catch (error) {
            console.error("Failed to fetch order details", error);
        } finally {
            setLoading(false);
        }
    };

    const handleDownloadInvoice = async () => {
        if (!order) return;
        try {
            await orderService.downloadInvoice(order._id);
        } catch (error) {
            console.error("Failed to download invoice", error);
        }
    };

    if (loading) {
        return (
            <div className="flex justify-center py-20">
                <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-emerald-500"></div>
            </div>
        );
    }

    if (!order) {
        return (
            <div className="container mx-auto px-4 py-8 text-center">
                <h2 className="text-xl font-bold text-gray-800">Order not found</h2>
                <Link to="/user/orders" className="text-emerald-500 hover:underline mt-4 inline-block">Back to My Orders</Link>
            </div>
        );
    }

    // Status Steps Logic
    const steps = [
        { status: 'processing', label: 'Processing', icon: FaBox },
        { status: 'shipped', label: 'Shipped', icon: FaTruck },
        { status: 'delivered', label: 'Delivered', icon: FaCheckCircle },
    ];

    const currentStepIndex = steps.findIndex(s => s.status === order.status);
    // If cancelled, show red
    const isCancelled = order.status === 'cancelled';

    return (
        <div className="container mx-auto px-4 py-8 bg-gray-50 min-h-screen">
            <div className="mb-6">
                <Link to="/user/orders" className="flex items-center text-gray-500 hover:text-emerald-500 transition-colors">
                    <FaArrowLeft className="mr-2" /> Back to Orders
                </Link>
            </div>

            <div className="flex flex-col lg:flex-row gap-8">
                <UserSidebar />

                <div className="flex-1 space-y-6">
                    {/* Header & Actions */}
                    <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                        <div>
                            <div className="flex items-center gap-3">
                                <h1 className="text-xl font-bold text-gray-800">Order #{order._id.slice(-6).toUpperCase()}</h1>
                                <span className={`px-3 py-1 text-xs font-semibold rounded-full 
                                    ${order.status === 'delivered' ? 'bg-green-100 text-green-800' :
                                        order.status === 'cancelled' ? 'bg-red-100 text-red-800' :
                                            'bg-blue-100 text-blue-800'}`}>
                                    {order.status.toUpperCase()}
                                </span>
                            </div>
                            <p className="text-gray-500 text-sm mt-1">Placed on {new Date(order.createdAt).toLocaleDateString()}</p>
                        </div>
                        {order.status !== 'cancelled' && (
                            <button
                                onClick={handleDownloadInvoice}
                                className="flex items-center px-4 py-2 bg-emerald-500 text-white rounded-lg hover:bg-emerald-600 transition-colors shadow-sm"
                            >
                                <FaDownload className="mr-2" /> Download Invoice
                            </button>
                        )}
                    </div>

                    {/* Status Tracker */}
                    {!isCancelled && (
                        <div className="bg-white p-8 rounded-xl shadow-sm border border-gray-100">
                            <div className="relative flex justify-between">
                                {/* Track Line */}
                                <div className="absolute top-1/2 left-0 w-full h-1 bg-gray-200 -z-0 transform -translate-y-1/2 rounded-full"></div>
                                <div
                                    className="absolute top-1/2 left-0 h-1 bg-emerald-500 -z-0 transform -translate-y-1/2 rounded-full transition-all duration-500"
                                    style={{ width: `${((currentStepIndex) / (steps.length - 1)) * 100}%` }}
                                ></div>

                                {steps.map((step, index) => {
                                    const isCompleted = index <= currentStepIndex;
                                    const isCurrent = index === currentStepIndex;
                                    const Icon = step.icon;

                                    return (
                                        <div key={step.status} className="relative z-10 flex flex-col items-center bg-white px-2">
                                            <div className={`w-10 h-10 rounded-full flex items-center justify-center border-2 transition-colors duration-300
                                                ${isCompleted ? 'bg-emerald-500 border-emerald-500 text-white' : 'bg-white border-gray-300 text-gray-300'}
                                            `}>
                                                <Icon className="w-5 h-5" />
                                            </div>
                                            <span className={`mt-2 text-sm font-medium ${isCompleted ? 'text-gray-800' : 'text-gray-400'}`}>
                                                {step.label}
                                            </span>
                                            {isCurrent && (
                                                <span className="text-xs text-emerald-500 mt-1 font-semibold animate-pulse">Current</span>
                                            )}
                                        </div>
                                    );
                                })}
                            </div>
                        </div>
                    )}

                    {isCancelled && (
                        <div className="bg-red-50 border border-red-100 p-6 rounded-xl text-center text-red-800">
                            <h3 className="font-bold mb-2">Order Cancelled</h3>
                            <p>Reason: {order.cancellationReason || 'Cancelled by user'}</p>
                        </div>
                    )}

                    <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                        {/* Order Items */}
                        <div className="lg:col-span-2 bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
                            <div className="p-4 border-b border-gray-100 font-bold text-gray-800">Item Details</div>
                            <div className="divide-y divide-gray-100">
                                {order.products.map((item: any) => (
                                    <div key={item._id} className="p-4 flex gap-4">
                                        <img
                                            src={item.product?.imageUrl || 'https://via.placeholder.com/80'}
                                            alt={item.product?.name}
                                            className="w-20 h-20 object-cover rounded-lg border border-gray-100"
                                        />
                                        <div className="flex-1">
                                            <h4 className="font-medium text-gray-800">{item.product?.name}</h4>
                                            <p className="text-sm text-gray-500">Unit Price: Rs. {item.price}</p>
                                            <p className="text-sm text-gray-500">Qty: {item.quantity}</p>
                                        </div>
                                        <div className="font-bold text-gray-800">
                                            Rs. {item.price * item.quantity}
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>

                        {/* Order Summary & Address */}
                        <div className="space-y-6">
                            <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-6">
                                <h3 className="font-bold text-gray-800 mb-4 border-b border-gray-100 pb-2">Delivery Address</h3>
                                <div className="text-gray-600 text-sm space-y-1">
                                    <p className="font-medium text-gray-800">{order.address.name}</p>
                                    <p>{order.address.address}</p>
                                    <p>PIN: {order.address.pincode}</p>
                                    <p className="mt-2 flex items-center">
                                        <span className="font-medium">Phone:</span> {order.address.mobileNum}
                                    </p>
                                </div>
                            </div>

                            <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-6">
                                <h3 className="font-bold text-gray-800 mb-4 border-b border-gray-100 pb-2">Order Summary</h3>
                                <div className="space-y-2 text-sm">
                                    <div className="flex justify-between text-gray-600">
                                        <span>Subtotal</span>
                                        <span>Rs. {order.totalAmount}</span>
                                    </div>
                                    <div className="flex justify-between text-gray-600">
                                        <span>Shipping</span>
                                        <span className="text-green-600">Free</span>
                                    </div>
                                    <div className="border-t border-gray-100 pt-2 mt-2 flex justify-between font-bold text-lg text-gray-800">
                                        <span>Total</span>
                                        <span>Rs. {order.totalAmount}</span>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default OrderDetails;

import React, { useEffect, useState } from 'react';
import UserSidebar from '../../components/layout/UserSidebar';
import { orderService, Order } from '../../services/orderService';
import { FaBoxOpen, FaDownload, FaSearch, FaFilter } from 'react-icons/fa';
import { Link } from 'react-router-dom';

const OrderHistory: React.FC = () => {
    const [orders, setOrders] = useState<Order[]>([]);
    const [filteredOrders, setFilteredOrders] = useState<Order[]>([]);
    const [loading, setLoading] = useState(true);
    const [activeTab, setActiveTab] = useState('all');
    const [searchTerm, setSearchTerm] = useState('');

    useEffect(() => {
        fetchOrders();
    }, []);

    const fetchOrders = async () => {
        try {
            const data = await orderService.getMyOrders();
            // Assuming data.orders is the array
            const orderList = data.orders || [];
            setOrders(orderList);
            setFilteredOrders(orderList);
        } catch (error) {
            console.error("Failed to fetch orders", error);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        let result = orders;

        // Filter by tab
        if (activeTab !== 'all') {
            result = result.filter(order => order.status === activeTab);
        }

        // Filter by search (Order ID or Product Name)
        if (searchTerm) {
            const lowerTerm = searchTerm.toLowerCase();
            result = result.filter(order =>
                order._id.toLowerCase().includes(lowerTerm) ||
                order.products.some(p => p.product.name.toLowerCase().includes(lowerTerm))
            );
        }

        setFilteredOrders(result);
    }, [activeTab, searchTerm, orders]);

    const handleDownloadInvoice = async (orderId: string, e: React.MouseEvent) => {
        e.preventDefault();
        e.stopPropagation();
        try {
            await orderService.downloadInvoice(orderId);
        } catch (error) {
            console.error("Failed to download invoice", error);
            alert("Failed to download invoice. Please try again.");
        }
    };

    const getStatusColor = (status: string) => {
        switch (status) {
            case 'delivered': return 'bg-green-100 text-green-800';
            case 'processing': return 'bg-blue-100 text-blue-800';
            case 'shipped': return 'bg-purple-100 text-purple-800';
            case 'cancelled': return 'bg-red-100 text-red-800';
            default: return 'bg-yellow-100 text-yellow-800';
        }
    };

    return (
        <div className="container mx-auto px-4 py-8 bg-gray-50 min-h-screen">
            <div className="flex flex-col md:flex-row gap-8">
                <UserSidebar />

                <div className="flex-1 space-y-6">
                    <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-6">
                        <div className="flex flex-col md:flex-row justify-between items-center mb-6 gap-4">
                            <h2 className="text-xl font-bold text-gray-800 flex items-center">
                                <FaBoxOpen className="mr-2 text-emerald-500" /> My Orders
                            </h2>
                            <div className="relative w-full md:w-64">
                                <FaSearch className="absolute left-3 top-3 text-gray-400" />
                                <input
                                    type="text"
                                    placeholder="Search by Order ID or Product"
                                    className="w-full pl-10 pr-4 py-2 border border-gray-200 rounded-lg focus:ring-2 focus:ring-emerald-500 outline-none"
                                    value={searchTerm}
                                    onChange={(e) => setSearchTerm(e.target.value)}
                                />
                            </div>
                        </div>

                        {/* Tabs */}
                        <div className="flex border-b border-gray-100 mb-6 overflow-x-auto">
                            {['all', 'processing', 'shipped', 'delivered', 'cancelled'].map((tab) => (
                                <button
                                    key={tab}
                                    onClick={() => setActiveTab(tab)}
                                    className={`px-6 py-3 font-medium text-sm whitespace-nowrap transition-colors border-b-2 
                                        ${activeTab === tab
                                            ? 'border-emerald-500 text-emerald-600'
                                            : 'border-transparent text-gray-500 hover:text-gray-700'}`}
                                >
                                    {tab.charAt(0).toUpperCase() + tab.slice(1)}
                                </button>
                            ))}
                        </div>

                        {loading ? (
                            <div className="flex justify-center py-12">
                                <div className="animate-spin rounded-full h-8 w-8 border-t-2 border-b-2 border-emerald-500"></div>
                            </div>
                        ) : filteredOrders.length > 0 ? (
                            <div className="space-y-4">
                                {filteredOrders.map((order) => (
                                    <div key={order._id} className="border border-gray-200 rounded-xl p-6 hover:shadow-md transition-shadow bg-white">
                                        <div className="flex flex-col md:flex-row justify-between mb-4 border-b border-gray-50 pb-4">
                                            <div>
                                                <p className="text-sm text-gray-500 mb-1">Order Placed</p>
                                                <p className="font-medium text-gray-800">{new Date(order.createdAt).toLocaleDateString()}</p>
                                            </div>
                                            <div>
                                                <p className="text-sm text-gray-500 mb-1">Total Amount</p>
                                                <p className="font-medium text-gray-800">Rs. {order.totalAmount}</p>
                                            </div>
                                            <div>
                                                <p className="text-sm text-gray-500 mb-1">Order ID</p>
                                                <p className="font-medium text-gray-800">#{order._id.slice(-6).toUpperCase()}</p>
                                            </div>
                                            <div className="mt-4 md:mt-0">
                                                <span className={`px-3 py-1 text-xs font-semibold rounded-full ${getStatusColor(order.status)}`}>
                                                    {order.status.toUpperCase()}
                                                </span>
                                            </div>
                                        </div>

                                        <div className="flex flex-col md:flex-row gap-4 items-center">
                                            {/* Product Previews */}
                                            <div className="flex-1 flex gap-4 overflow-x-auto pb-2">
                                                {order.products.slice(0, 3).map((item, idx) => (
                                                    <div key={idx} className="flex items-center gap-3 min-w-[200px]">
                                                        <img
                                                            src={item.product.imageUrl}
                                                            alt={item.product.name}
                                                            className="w-16 h-16 object-cover rounded-md border border-gray-100"
                                                        />
                                                        <div>
                                                            <p className="text-sm font-medium text-gray-800 line-clamp-1">{item.product.name}</p>
                                                            <p className="text-xs text-gray-500">Qty: {item.quantity}</p>
                                                        </div>
                                                    </div>
                                                ))}
                                                {order.products.length > 3 && (
                                                    <div className="flex items-center justify-center w-16 h-16 bg-gray-50 rounded-md text-gray-500 text-xs font-medium">
                                                        +{order.products.length - 3} more
                                                    </div>
                                                )}
                                            </div>

                                            {/* Actions */}
                                            <div className="flex gap-3 w-full md:w-auto mt-4 md:mt-0">
                                                <Link
                                                    to={`/user/orders/${order._id}`}
                                                    className="flex-1 md:flex-none px-4 py-2 border border-emerald-500 text-emerald-600 rounded-lg hover:bg-emerald-50 transition-colors text-sm font-medium text-center"
                                                >
                                                    View Details
                                                </Link>
                                                {order.status !== 'cancelled' && (
                                                    <button
                                                        onClick={(e) => handleDownloadInvoice(order._id, e)}
                                                        className="flex-1 md:flex-none flex items-center justify-center px-4 py-2 bg-emerald-500 text-white rounded-lg hover:bg-emerald-600 transition-colors text-sm font-medium"
                                                    >
                                                        <FaDownload className="mr-2" /> Invoice
                                                    </button>
                                                )}
                                            </div>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        ) : (
                            <div className="text-center py-12">
                                <div className="bg-gray-50 rounded-full w-16 h-16 flex items-center justify-center mx-auto mb-4">
                                    <FaBoxOpen className="text-gray-400 w-8 h-8" />
                                </div>
                                <h3 className="text-lg font-medium text-gray-900 mb-2">No orders found</h3>
                                <p className="text-gray-500 mb-6">Looks like you haven't placed any orders yet.</p>
                                <Link to="/" className="px-6 py-2 bg-emerald-500 text-white rounded-lg hover:bg-emerald-600 transition-colors font-medium">
                                    Start Shopping
                                </Link>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default OrderHistory;

import React, { useEffect, useState } from 'react';
import UserSidebar from '../../components/layout/UserSidebar';
import { useAuth } from '../../contexts/AuthContext';
import { orderService } from '../../services/orderService';
import { addressService } from '../../services/addressService';
import { wishlistService } from '../../services/wishlistService';
import { FaBox, FaShoppingBag, FaUserCheck, FaExclamationTriangle, FaMapMarkerAlt, FaHeart } from 'react-icons/fa';
import { Link } from 'react-router-dom';

const UserDashboard: React.FC = () => {
    const { user } = useAuth();
    const [stats, setStats] = useState({
        totalOrders: 0,
        pendingOrders: 0,
        wishlistItems: 0,
        savedAddresses: 0
    });
    const [recentOrders, setRecentOrders] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const fetchDashboardData = async () => {
            try {
                const [ordersResponse, addressResponse, wishlistRes] = await Promise.all([
                    orderService.getMyOrders(),
                    addressService.getAddresses(),
                    wishlistService.getWishlist()
                ]);

                const orders = ordersResponse.orders || [];
                const addresses = addressResponse.allAddress || addressResponse.address || [];

                setStats({
                    totalOrders: orders.length,
                    pendingOrders: orders.filter((o: any) => o.status === 'processing' || o.status === 'pending').length,
                    wishlistItems: wishlistRes.wishlist?.length || 0,
                    savedAddresses: addresses.length
                });

                setRecentOrders(orders.slice(0, 5));
            } catch (error) {
                console.error("Failed to fetch dashboard data", error);
            } finally {
                setLoading(false);
            }
        };

        fetchDashboardData();
    }, []);

    if (loading) {
        return (
            <div className="container mx-auto px-4 py-8 flex justify-center">
                <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-emerald-500"></div>
            </div>
        );
    }

    return (
        <div className="container mx-auto px-4 py-8 bg-gray-50 min-h-screen">
            <div className="flex flex-col md:flex-row gap-8">
                <UserSidebar />

                <div className="flex-1">
                    {/* Welcome Banner */}
                    <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-8 mb-8 relative overflow-hidden">
                        <div className="relative z-10">
                            <h1 className="text-3xl font-bold text-gray-800 mb-2">
                                Hello, {user?.firstName}! ≡ƒæï
                            </h1>
                            <p className="text-gray-500">
                                Welcome back to your account. Here's what's happening with your orders.
                            </p>
                        </div>
                        <div className="absolute right-0 top-0 h-full w-1/3 bg-emerald-50 rounded-l-full opacity-50 transform translate-x-10"></div>
                    </div>

                    {/* Stats Grid */}
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
                        <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 flex items-center">
                            <div className="p-4 bg-blue-50 text-blue-500 rounded-full mr-4">
                                <FaShoppingBag className="w-6 h-6" />
                            </div>
                            <div>
                                <p className="text-gray-500 text-sm">Total Orders</p>
                                <p className="text-2xl font-bold text-gray-800">{stats.totalOrders}</p>
                            </div>
                        </div>

                        <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 flex items-center">
                            <div className="p-4 bg-orange-50 text-orange-500 rounded-full mr-4">
                                <FaBox className="w-6 h-6" />
                            </div>
                            <div>
                                <p className="text-gray-500 text-sm">Pending Orders</p>
                                <p className="text-2xl font-bold text-gray-800">{stats.pendingOrders}</p>
                            </div>
                        </div>

                        <Link to="/user/wishlist" className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 flex items-center hover:shadow-md transition-shadow group">
                            <div className="p-4 bg-red-50 text-red-500 rounded-full mr-4 group-hover:bg-red-100 transition-colors">
                                <FaHeart className="w-6 h-6" />
                            </div>
                            <div>
                                <p className="text-gray-500 text-sm">Wishlist Items</p>
                                <p className="text-2xl font-bold text-gray-800">{stats.wishlistItems}</p>
                            </div>
                        </Link>

                        <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 flex items-center">
                            <div className="p-4 bg-purple-50 text-purple-500 rounded-full mr-4">
                                <FaMapMarkerAlt className="w-6 h-6" />
                            </div>
                            <div>
                                <p className="text-gray-500 text-sm">Saved Addresses</p>
                                <p className="text-2xl font-bold text-gray-800">{stats.savedAddresses}</p>
                            </div>
                        </div>

                        <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 flex items-center">
                            <div className={`p-4 rounded-full mr-4 ${user?.isVerified ? 'bg-green-50 text-green-500' : 'bg-red-50 text-red-500'}`}>
                                {user?.isVerified ? <FaUserCheck className="w-6 h-6" /> : <FaExclamationTriangle className="w-6 h-6" />}
                            </div>
                            <div>
                                <p className="text-gray-500 text-sm">Account Status</p>
                                <p className={`text-lg font-bold ${user?.isVerified ? 'text-green-600' : 'text-red-500'}`}>
                                    {user?.isVerified ? 'Verified' : 'Unverified'}
                                </p>
                            </div>
                        </div>
                    </div>

                    {/* Recent Orders Preview */}
                    <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
                        <div className="px-6 py-4 border-b border-gray-100 flex justify-between items-center">
                            <h3 className="font-bold text-gray-800">Recent Orders</h3>
                            <Link to="/user/orders" className="text-emerald-500 hover:text-emerald-600 text-sm font-medium">
                                View All
                            </Link>
                        </div>

                        {recentOrders.length > 0 ? (
                            <div className="overflow-x-auto">
                                <table className="w-full text-left">
                                    <thead className="bg-gray-50 text-gray-600 text-xs uppercase">
                                        <tr>
                                            <th className="px-6 py-3 font-medium">Order ID</th>
                                            <th className="px-6 py-3 font-medium">Date</th>
                                            <th className="px-6 py-3 font-medium">Status</th>
                                            <th className="px-6 py-3 font-medium">Total</th>
                                            <th className="px-6 py-3 font-medium">Action</th>
                                        </tr>
                                    </thead>
                                    <tbody className="divide-y divide-gray-100">
                                        {recentOrders.map((order) => (
                                            <tr key={order._id} className="hover:bg-gray-50 transition-colors">
                                                <td className="px-6 py-4 text-sm font-medium text-gray-900">
                                                    #{order._id.slice(-6).toUpperCase()}
                                                </td>
                                                <td className="px-6 py-4 text-sm text-gray-500">
                                                    {new Date(order.createdAt).toLocaleDateString()}
                                                </td>
                                                <td className="px-6 py-4">
                                                    <span className={`px-3 py-1 text-xs font-semibold rounded-full 
                                                        ${order.status === 'delivered' ? 'bg-green-100 text-green-800' :
                                                            order.status === 'cancelled' ? 'bg-red-100 text-red-800' :
                                                                'bg-yellow-100 text-yellow-800'}`}>
                                                        {order.status.charAt(0).toUpperCase() + order.status.slice(1)}
                                                    </span>
                                                </td>
                                                <td className="px-6 py-4 text-sm font-medium text-gray-900">
                                                    Rs. {order.totalAmount}
                                                </td>
                                                <td className="px-6 py-4 text-sm">
                                                    <Link to={`/user/orders/${order._id}`} className="text-emerald-500 hover:text-emerald-700 font-medium">
                                                        View Details
                                                    </Link>
                                                </td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                        ) : (
                            <div className="p-8 text-center text-gray-500">
                                <p>No orders yet. Start shopping!</p>
                                <Link to="/" className="inline-block mt-4 px-6 py-2 bg-emerald-500 text-white rounded-lg hover:bg-emerald-600 transition-colors">
                                    Browse Products
                                </Link>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default UserDashboard;

import React, { useEffect, useState } from 'react';
import UserSidebar from '../../components/layout/UserSidebar';
import { useAuth } from '../../contexts/AuthContext';
import { authService } from '../../services/authService';
import { addressService, Address } from '../../services/addressService';
import { FaPlus, FaTrash, FaMapMarkerAlt, FaUser, FaEdit, FaSave, FaTimes } from 'react-icons/fa';
import toast from 'react-hot-toast';

const UserProfile: React.FC = () => {
    const { user, setUser } = useAuth();
    const [addresses, setAddresses] = useState<Address[]>([]);
    const [loading, setLoading] = useState(true);
    const [isEditing, setIsEditing] = useState(false);
    const [editForm, setEditForm] = useState({
        firstName: user?.firstName || '',
        lastName: user?.lastName || '',
        phoneNumber: user?.phoneNumber || ''
    });
    const [showAddModal, setShowAddModal] = useState(false);
    const [newAddress, setNewAddress] = useState<Address>({
        name: '',
        mobileNum: '',
        address: '',
        pincode: ''
    });

    useEffect(() => {
        fetchAddresses();
        if (user) {
            setEditForm({
                firstName: user.firstName || '',
                lastName: user.lastName || '',
                phoneNumber: user.phoneNumber || ''
            });
        }
    }, [user]);

    const handleUpdateProfile = async (e: React.FormEvent) => {
        e.preventDefault();
        try {
            const data = await authService.updateProfile(editForm);
            if (data.success) {
                if (setUser) setUser(data.user);
                setIsEditing(false);
                toast.success('Profile updated successfully');
            }
        } catch (error: any) {
            toast.error(error.response?.data?.message || 'Failed to update profile');
        }
    };

    const fetchAddresses = async () => {
        try {
            const data = await addressService.getAddresses();
            const fetchedAddresses = data.allAddress || data.address || data.addresses || (Array.isArray(data) ? data : []);
            setAddresses(fetchedAddresses);
        } catch (error) {
            console.error("Failed to fetch addresses", error);
        } finally {
            setLoading(false);
        }
    };

    const handleAddAddress = async (e: React.FormEvent) => {
        e.preventDefault();
        try {
            await addressService.addAddress(newAddress);
            setShowAddModal(false);
            setNewAddress({ name: '', mobileNum: '', address: '', pincode: '' });
            fetchAddresses();
            toast.success('Address added');
        } catch (error) {
            toast.error('Failed to add address');
        }
    };

    const handleDeleteAddress = async (id: string) => {
        if (window.confirm("Are you sure you want to delete this address?")) {
            try {
                await addressService.deleteAddress(id);
                fetchAddresses();
                toast.success('Address deleted');
            } catch (error) {
                toast.error('Failed to delete address');
            }
        }
    };

    return (
        <div className="container mx-auto px-4 py-8 bg-gray-50 min-h-screen">
            <div className="flex flex-col md:flex-row gap-8">
                <UserSidebar />

                <div className="flex-1 space-y-6">
                    {/* Personal Information */}
                    <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-6">
                        <div className="flex justify-between items-center mb-6">
                            <h2 className="text-xl font-bold text-gray-800 flex items-center">
                                <FaUser className="mr-2 text-emerald-500" /> Personal Information
                            </h2>
                            {!isEditing ? (
                                <button
                                    onClick={() => setIsEditing(true)}
                                    className="flex items-center px-4 py-2 text-blue-600 hover:bg-blue-50 rounded-lg transition-colors text-sm font-medium"
                                >
                                    <FaEdit className="mr-2" /> Edit Info
                                </button>
                            ) : (
                                <div className="flex gap-2">
                                    <button
                                        onClick={() => setIsEditing(false)}
                                        className="flex items-center px-4 py-2 text-gray-500 hover:bg-gray-50 rounded-lg transition-colors text-sm font-medium"
                                    >
                                        <FaTimes className="mr-2" /> Cancel
                                    </button>
                                    <button
                                        form="profile-form"
                                        type="submit"
                                        className="flex items-center px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors text-sm font-medium"
                                    >
                                        <FaSave className="mr-2" /> Save Changes
                                    </button>
                                </div>
                            )}
                        </div>

                        <form id="profile-form" onSubmit={handleUpdateProfile}>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                <div>
                                    <label className="block text-sm font-medium text-gray-500 mb-1">First Name</label>
                                    {isEditing ? (
                                        <input
                                            type="text"
                                            className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-emerald-500 outline-none"
                                            value={editForm.firstName}
                                            onChange={e => setEditForm({ ...editForm, firstName: e.target.value })}
                                            required
                                        />
                                    ) : (
                                        <div className="p-3 bg-gray-50 rounded-lg text-gray-800 font-medium capitalize">
                                            {user?.firstName}
                                        </div>
                                    )}
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-gray-500 mb-1">Last Name</label>
                                    {isEditing ? (
                                        <input
                                            type="text"
                                            className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-emerald-500 outline-none"
                                            value={editForm.lastName}
                                            onChange={e => setEditForm({ ...editForm, lastName: e.target.value })}
                                            required
                                        />
                                    ) : (
                                        <div className="p-3 bg-gray-50 rounded-lg text-gray-800 font-medium capitalize">
                                            {user?.lastName}
                                        </div>
                                    )}
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-gray-500 mb-1">Phone Number</label>
                                    {isEditing ? (
                                        <input
                                            type="text"
                                            className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-emerald-500 outline-none"
                                            value={editForm.phoneNumber}
                                            onChange={e => setEditForm({ ...editForm, phoneNumber: e.target.value })}
                                            required
                                        />
                                    ) : (
                                        <div className="p-3 bg-gray-50 rounded-lg text-gray-800 font-medium">
                                            {user?.phoneNumber}
                                        </div>
                                    )}
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-gray-500 mb-1">Email Address</label>
                                    <div className="p-3 bg-gray-50 rounded-lg text-gray-400 font-medium">
                                        {user?.email}
                                    </div>
                                    <p className="text-[10px] text-gray-400 mt-1 italic">* Email cannot be changed</p>
                                </div>
                            </div>
                        </form>
                    </div>

                    {/* Address Management */}
                    <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-6">
                        <div className="flex justify-between items-center mb-6">
                            <h2 className="text-xl font-bold text-gray-800 flex items-center">
                                <FaMapMarkerAlt className="mr-2 text-emerald-500" /> Saved Addresses
                            </h2>
                            <button
                                onClick={() => setShowAddModal(true)}
                                className="flex items-center px-4 py-2 bg-emerald-500 text-white rounded-lg hover:bg-emerald-600 transition-colors text-sm font-medium"
                            >
                                <FaPlus className="mr-2" /> Add New
                            </button>
                        </div>

                        {loading ? (
                            <div className="text-center py-4">Loading addresses...</div>
                        ) : addresses.length > 0 ? (
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                {addresses.map((addr: any) => (
                                    <div key={addr._id} className="border border-gray-200 rounded-lg p-4 hover:border-emerald-500 transition-colors relative group">
                                        <button
                                            onClick={() => handleDeleteAddress(addr._id)}
                                            className="absolute top-4 right-4 text-gray-400 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"
                                        >
                                            <FaTrash />
                                        </button>
                                        <h3 className="font-bold text-gray-800 mb-1">{addr.name}</h3>
                                        <p className="text-gray-600 text-sm mb-1">{addr.address}</p>
                                        <p className="text-gray-600 text-sm mb-2">Pin: {addr.pincode}</p>
                                        <p className="text-gray-800 text-sm font-medium">Ph: {addr.mobileNum}</p>
                                    </div>
                                ))}
                            </div>
                        ) : (
                            <div className="text-center py-8 text-gray-500 bg-gray-50 rounded-lg border border-dashed border-gray-300">
                                No addresses saved. Add one to checkout faster!
                            </div>
                        )}
                    </div>
                </div>
            </div>

            {/* Add Address Modal */}
            {showAddModal && (
                <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50">
                    <div className="bg-white rounded-xl shadow-xl max-w-md w-full p-6">
                        <h3 className="text-lg font-bold text-gray-800 mb-4">Add New Address</h3>
                        <form onSubmit={handleAddAddress}>
                            <div className="space-y-4">
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1">Name</label>
                                    <input
                                        type="text"
                                        required
                                        className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-emerald-500 focus:border-transparent outline-none"
                                        value={newAddress.name}
                                        onChange={e => setNewAddress({ ...newAddress, name: e.target.value })}
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1">Mobile Number</label>
                                    <input
                                        type="text"
                                        required
                                        className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-emerald-500 focus:border-transparent outline-none"
                                        value={newAddress.mobileNum}
                                        onChange={e => setNewAddress({ ...newAddress, mobileNum: e.target.value })}
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1">Address</label>
                                    <textarea
                                        required
                                        className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-emerald-500 focus:border-transparent outline-none"
                                        rows={3}
                                        value={newAddress.address}
                                        onChange={e => setNewAddress({ ...newAddress, address: e.target.value })}
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1">Pincode</label>
                                    <input
                                        type="text"
                                        required
                                        className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-emerald-500 focus:border-transparent outline-none"
                                        value={newAddress.pincode}
                                        onChange={e => setNewAddress({ ...newAddress, pincode: e.target.value })}
                                    />
                                </div>
                            </div>
                            <div className="flex justify-end gap-3 mt-6">
                                <button
                                    type="button"
                                    onClick={() => setShowAddModal(false)}
                                    className="px-4 py-2 text-gray-600 hover:bg-gray-100 rounded-lg transition-colors"
                                >
                                    Cancel
                                </button>
                                <button
                                    type="submit"
                                    className="px-6 py-2 bg-emerald-500 text-white rounded-lg hover:bg-emerald-600 transition-colors shadow-sm"
                                >
                                    Save Address
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
};

export default UserProfile;

import React, { useEffect, useState } from 'react';
import UserSidebar from '../../components/layout/UserSidebar';
import { wishlistService } from '../../services/wishlistService';
import { useCart } from '../../contexts/CartContext';
import { FaHeart, FaTrash, FaShoppingCart } from 'react-icons/fa';
import toast from 'react-hot-toast';
import { Link } from 'react-router-dom';

const Wishlist: React.FC = () => {
    const [wishlistItems, setWishlistItems] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const { addToCart } = useCart();

    useEffect(() => {
        fetchWishlist();
    }, []);

    const fetchWishlist = async () => {
        try {
            const response = await wishlistService.getWishlist();
            if (response.success) {
                setWishlistItems(response.wishlist || []);
            }
        } catch (error) {
            console.error("Failed to fetch wishlist", error);
            toast.error("Failed to load wishlist");
        } finally {
            setLoading(false);
        }
    };

    const handleRemove = async (productId: string) => {
        try {
            const response = await wishlistService.removeFromWishlist(productId);
            if (response.success) {
                toast.success("Removed from wishlist");
                setWishlistItems(prev => prev.filter(item => item._id !== productId));
            }
        } catch (error) {
            toast.error("Failed to remove item");
        }
    };

    const handleAddToCart = (product: any) => {
        addToCart(product, 1);
        handleRemove(product._id);
    };

    if (loading) {
        return (
            <div className="container mx-auto px-4 py-8 flex justify-center">
                <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-emerald-500"></div>
            </div>
        );
    }

    return (
        <div className="container mx-auto px-4 py-8 bg-gray-50 min-h-screen">
            <div className="flex flex-col md:flex-row gap-8">
                <UserSidebar />

                <div className="flex-1">
                    <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-8 mb-8">
                        <h1 className="text-3xl font-bold text-gray-800 mb-2 flex items-center">
                            <FaHeart className="text-red-500 mr-3" /> My Wishlist
                        </h1>
                        <p className="text-gray-500">Items you've saved for later.</p>
                    </div>

                    {wishlistItems.length > 0 ? (
                        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
                            {wishlistItems.map((item) => (
                                <div key={item._id} className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden hover:shadow-md transition-shadow flex flex-col">
                                    <div className="relative h-48 bg-gray-50">
                                        <img
                                            src={item.imageUrl?.url || item.imageUrl || '/placeholder.png'}
                                            alt={item.name}
                                            className="w-full h-full object-contain p-4"
                                        />
                                        <button
                                            onClick={() => handleRemove(item._id)}
                                            className="absolute top-3 right-3 p-2 bg-white rounded-full shadow-sm text-gray-400 hover:text-red-500 transition-colors"
                                        >
                                            <FaTrash className="w-4 h-4" />
                                        </button>
                                    </div>
                                    <div className="p-4 flex-1 flex flex-col">
                                        <h3 className="font-bold text-gray-800 line-clamp-2 mb-1">{item.name}</h3>
                                        <p className="text-sm text-gray-500 mb-3">{item.brand}</p>
                                        <div className="mt-auto">
                                            <div className="text-xl font-bold text-blue-600 mb-4">Γé╣{item.price}</div>
                                            <div className="flex gap-2">
                                                <button
                                                    onClick={() => handleAddToCart(item)}
                                                    className="flex-1 bg-emerald-500 text-white py-2 rounded-lg flex items-center justify-center gap-2 hover:bg-emerald-600 transition-colors font-semibold"
                                                >
                                                    <FaShoppingCart className="w-4 h-4" /> Add to Cart
                                                </button>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    ) : (
                        <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-12 text-center">
                            <div className="w-20 h-20 bg-gray-50 rounded-full flex items-center justify-center mx-auto mb-4">
                                <FaHeart className="text-gray-300 w-10 h-10" />
                            </div>
                            <h2 className="text-xl font-bold text-gray-800 mb-2">Your wishlist is empty</h2>
                            <p className="text-gray-500 mb-6">Looks like you haven't added anything to your wishlist yet.</p>
                            <Link to="/" className="inline-block px-8 py-3 bg-blue-600 text-white rounded-lg font-bold hover:bg-blue-700 transition-colors">
                                Explore Products
                            </Link>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

export default Wishlist;

import api from './api';

export interface WishlistResponse {
    success: number;
    message: string;
    wishlist: any[];
}

export const wishlistService = {
    // Get user's wishlist
    getWishlist: async (): Promise<WishlistResponse> => {
        const response = await api.get('/user/fetchWishlist');
        return response.data;
    },

    // Add product to wishlist
    addToWishlist: async (productId: string): Promise<WishlistResponse> => {
        const response = await api.post(`/user/addWishlist/${productId}`);
        return response.data;
    },

    // Remove product from wishlist
    removeFromWishlist: async (productId: string): Promise<WishlistResponse> => {
        const response = await api.delete(`/user/deleteWishlist/${productId}`);
        return response.data;
    }
};
